"use client"

import { useEffect, useRef } from "react"

/**
 * Ambient particle-network background: nodes drift slowly and connect with
 * fading lines when close. No mouse interaction, light on performance.
 * Renders onto a transparent canvas meant to sit over a dark gradient.
 */
export function ParticleNetwork({ className }: { className?: string }) {
  const ref = useRef<HTMLCanvasElement>(null)

  useEffect(() => {
    const canvas = ref.current
    if (!canvas) return
    const ctx = canvas.getContext("2d")
    if (!ctx) return

    const dpr = Math.min(window.devicePixelRatio || 1, 2)
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    const colors = ["#22d3ee", "#a78bfa", "#ffffff", "#7c3aed"]
    const MAX_DIST = 132

    type Point = { x: number; y: number; vx: number; vy: number; r: number; c: string }
    let w = 0
    let h = 0
    let points: Point[] = []
    let raf = 0

    function init() {
      const parent = canvas!.parentElement
      w = parent ? parent.clientWidth : window.innerWidth
      h = parent ? parent.clientHeight : window.innerHeight
      canvas!.width = w * dpr
      canvas!.height = h * dpr
      canvas!.style.width = w + "px"
      canvas!.style.height = h + "px"
      ctx!.setTransform(dpr, 0, 0, dpr, 0, 0)

      const count = Math.max(28, Math.min(75, Math.floor((w * h) / 16000)))
      points = Array.from({ length: count }, () => ({
        x: Math.random() * w,
        y: Math.random() * h,
        vx: (Math.random() - 0.5) * 0.24,
        vy: (Math.random() - 0.5) * 0.24,
        r: Math.random() * 1.5 + 0.8,
        c: colors[Math.floor(Math.random() * colors.length)],
      }))
    }

    function draw() {
      ctx!.clearRect(0, 0, w, h)

      for (const p of points) {
        p.x += p.vx
        p.y += p.vy
        if (p.x < -12) p.x = w + 12
        else if (p.x > w + 12) p.x = -12
        if (p.y < -12) p.y = h + 12
        else if (p.y > h + 12) p.y = -12
      }

      for (let i = 0; i < points.length; i++) {
        for (let j = i + 1; j < points.length; j++) {
          const a = points[i]
          const b = points[j]
          const dx = a.x - b.x
          const dy = a.y - b.y
          const d = Math.hypot(dx, dy)
          if (d < MAX_DIST) {
            ctx!.strokeStyle = `rgba(165, 155, 245, ${(1 - d / MAX_DIST) * 0.32})`
            ctx!.lineWidth = 0.7
            ctx!.beginPath()
            ctx!.moveTo(a.x, a.y)
            ctx!.lineTo(b.x, b.y)
            ctx!.stroke()
          }
        }
      }

      for (const p of points) {
        ctx!.beginPath()
        ctx!.arc(p.x, p.y, p.r, 0, Math.PI * 2)
        ctx!.fillStyle = p.c
        ctx!.globalAlpha = 0.85
        ctx!.fill()
        ctx!.globalAlpha = 1
      }
    }

    function loop() {
      draw()
      raf = requestAnimationFrame(loop)
    }

    init()
    if (reduce) {
      draw()
    } else {
      raf = requestAnimationFrame(loop)
    }

    const onResize = () => init()
    window.addEventListener("resize", onResize)
    return () => {
      cancelAnimationFrame(raf)
      window.removeEventListener("resize", onResize)
    }
  }, [])

  return <canvas ref={ref} className={className} aria-hidden="true" />
}
